function shortestPathLengths(graph, start) {
  const dist = new Map([[start, 0]]);
  const queue = [start];

  while (queue.length > 0) {
    const node = queue.shift();
    for (const next of graph.neighbors(node)) {
      if (dist.has(next)) continue;
      dist.set(next, dist.get(node) + 1);   // one more layer out
      queue.push(next);
    }
  }

  return dist;
}

function dfs(graph, node, seen = new Set()) {
  seen.add(node);
  for (const next of graph.neighbors(node)) {
    if (!seen.has(next)) dfs(graph, next, seen);
  }
  return seen;
}

from collections import deque

def bfs_bad(graph, start):
    queue = deque([start])
    visited = set()
    push_count = 0  # Tracks queue entries

    while queue:
        current = queue.popleft()

        # BAD: Marking as visited ONLY when taking it out
        if current in visited:
            continue
        visited.add(current)

        for neighbor in graph[current]:
            if neighbor not in visited:
                queue.append(neighbor)
                push_count += 1

    return push_count

function traverse(graph, start, mode) {
  const seen = new Set([start]);     // mark on the way IN, not on the way out
  const pending = [start];
  const order = [];

  while (pending.length > 0) {
    const node = mode === "bfs" ? pending.shift() : pending.pop(); // only change
    order.push(node);

    for (const next of graph.neighbors(node)) {
      if (seen.has(next)) continue;
      seen.add(next);
      pending.push(next);
    }
  }

  return order;
}

