vector<int> traverse(const vector<vector<int>>& adj, int start, bool bfs) {
    vector<bool> seen(adj.size(), false);
    seen[start] = true;               // mark on the way IN, not on the way out
    deque<int> pending{start};
    vector<int> order;

    while (!pending.empty()) {
        // small difference
        int node = bfs ? pending.front() : pending.back();
        bfs ? pending.pop_front() : pending.pop_back();
        order.push_back(node);

        for (int next : adj[node]) {
            if (seen[next]) continue;
            seen[next] = true;
            pending.push_back(next);
        }
    }
    return order;
}
